// src/api/axios.js
import { IS_DEMO } from "../api/demoConfig";
import { mockGet, mockPost, mockPut, mockPatch, mockDelete } from "./mockDemo";

const axios_api = {
  get: async (path, opts = {}) => {
    if (IS_DEMO) {
      const data = mockGet(path, opts);
      return { data };
    }
    // 데모 외 모드 고려 안 함 (너 지금 데모만 쓸 거니까)
  },

  post: async (path, body, opts = {}) => {
    if (IS_DEMO) {
      const data = mockPost(path, body, opts);
      return { data };
    }
  },

  put: async (path, body, opts = {}) => {
    if (IS_DEMO) {
      const data = mockPut(path, body, opts);
      return { data };
    }
  },

  patch: async (path, body, opts = {}) => {
    if (IS_DEMO) {
      const data = mockPatch(path, body, opts);
      return { data };
    }
  },

  delete: async (path, opts = {}) => {
    if (IS_DEMO) {
      return { data: mockDelete(path, opts) };
    }
  },
};

export default axios_api;
